async function search(query, chunks){
  const q = await embed(query);
  const sims = chunks.map(c => ({ chunk: c, score: cosine(q, c.vec) }));
  sims.sort((a,b) => b.score - a.score);
  // simple re-ranking by term matches
  return sims.slice(0,3).sort((a,b)=>hitScore(b.chunk, query) - hitScore(a.chunk, query));
